class PullRequestsDayBucket(EllipsisModel):
    """Pull-request activity on one UTC day. `prs`, `lines`, `authors`, and
    `commits` count pull requests created that day; `merged` and `merge_time`
    cover pull requests merged that day; `closed` counts pull requests closed
    without merging that day.

    Each created-keyed count also splits bots from humans: `*_bot` counts pull
    requests whose author is a bot (a Bot account or a `[bot]` login),
    `*_human` is everything else, so the pair always sums to the total.
    """

    authors: int = Field(
        description="Distinct pull-request authors active this day, humans and bots."
    )
    authors_bot: int = Field(description="Distinct bot authors active this day.")
    authors_human: int = Field(description="Distinct human authors active this day.")
    closed: int = Field(description="Pull requests closed without merging this day.")
    commits: int = Field(
        description="Total commits across pull requests created this day."
    )
    commits_bot: int = Field(
        description="Commits across pull requests created by bot authors."
    )
    commits_human: int = Field(
        description="Commits across pull requests created by human authors."
    )
    date: str = Field(description="The UTC day, formatted YYYY-MM-DD.")
    lines: int = Field(
        description="Lines added plus deleted across pull requests created this day."
    )
    lines_bot: int = Field(
        description="Lines across pull requests created by bot authors."
    )
    lines_human: int = Field(
        description="Lines across pull requests created by human authors."
    )
    merge_time: DurationPercentiles = Field(
        description="Time-to-merge percentiles, in hours, for pull requests merged this day."
    )
    merged: int = Field(description="Pull requests merged this day.")
    prs: int = Field(description="Pull requests created this day.")
    prs_bot: int = Field(description="Pull requests created this day by bot authors.")
    prs_human: int = Field(
        description="Pull requests created this day by human authors."
    )


