class ReviewedCommit(EllipsisModel):
    """One commit inside a run's reviewed range, snapshotted at mint time.

    Stored rather than re-derived: `watermark...head` is only resolvable against
    the PR's history as it was when the run was minted, and a force-push (or a
    merge) makes those SHAs unreachable — the range would then render as two
    orphan SHAs forever. The mint path already holds the PR's ordered commit
    list, so this costs no extra GitHub call.
    """

