"""The durable conversation axis (backs the surfaced `session` field)."""


class SessionSurface(EllipsisModel):
    """The three fields we expose.

    `use_enum_values=True` (from CustomBaseModel) stores the members as their
    string values, so this serializes to `{"session": "alive", "run": "waiting",
    "status": "waiting"}` — a plain object, not enum names.
    """

    run: Union[RunStatus, None]
    session: Union[SessionLiveness, None]
    status: Union[str, None]


class SessionTokens(EllipsisModel):
    """The token counts a session (or turn) spent, and the model they went to.

    `total` INCLUDES the cache lanes, unlike the old flat `tokens_total` which
    counted input+output+thinking only and left callers to add cache reads and
    writes back themselves (the deleted `tokensTotalAll` helper). Cache tokens
    dominate an agent run's token bill, so a "total" that omits them is the
    wrong default and produced two competing totals in the dashboard.
    """

    cache_creation: int = Field(
        default=0, description="Tokens written to the prompt cache."
    )
    cache_read: int = Field(default=0, description="Tokens read from the prompt cache.")
    input: int = Field(default=0, description="Input tokens used.")
    model: str = Field(
        default="", description="The model the token counts are attributed to."
    )
    output: int = Field(default=0, description="Output tokens used.")
    total: int = Field(
        default=0,
        description="Total tokens consumed, INCLUDING the prompt-cache reads and writes — the same basis the token cost is priced on.",
    )


