class StartAgentSessionRequest(EllipsisModel):
    """Parameters for starting a raw session: where it runs, its first
    message, and the run's own settings. Flat, in the AutomationConfig vocabulary
    — a `claude:` or `permissions:` block copied from an agents/ YAML file
    pastes in verbatim. There is no automation behind a raw session; to run a
    saved automation, invoke it with POST /v1/automations/{automation_id}/sessions.

    Extra keys are a 422, not silently dropped — a retired field
    (`from_config_id`, `input`, `ellipsis`, `config_id`) must fail loudly on
    an old client, never no-op.
    """

    budget: Union[float, None] = Field(
        default=None,
        description="The most this session may spend, in US dollars. Omitted, the organization's default applies. Above the organization's per-session ceiling is a 400.",
    )
    claude: Union[ClaudeConfig, None] = Field(
        default=None,
        description="The Claude-harness block: `{\"model\": ...}` to pick this session's model, plus system/effort/fallback_model/max_turns/settings. Omit the model to run the organization's default.",
    )
    codex: Union[CodexConfig, None] = Field(
        default=None,
        description="The Codex-harness block. Its presence selects the Codex harness, exactly as in a saved automation; a request may not carry both `claude` and `codex`.",
    )
    environment: Union[str, EnvironmentConfig, None] = Field(
        default=None,
        description="Where the session runs. A STRING is a saved environment's name or `env_...` id, substituted wholesale. An OBJECT is the whole environment for this session — `{}` is the bare sandbox. Omitted, the session runs in the built-in basic sandbox — nothing outside the request picks the environment.",
    )
    force_rebuild: bool = Field(
        default=False,
        description="Skip the image cache for this session's initial provision: a fresh full build whose snapshot then refreshes the cache for later runs. The CLI's `--rebuild`.",
    )
    images: Union[list[ImageAttachment], None] = Field(
        default=None,
        description="Images attached to the first message, base64 inline — what a paste into Claude Code sends. Each becomes an `[Image #N]` placeholder in the prompt and an image block the model sees on turn 0. Up to 10, 5 MiB each; PNG, JPEG, GIF, or WebP. Claude harness only.",
    )
    interactive: bool = Field(
        default=True,
        description="Whether the session stays open for messages after its first turn. Set false for a one-shot run that does its job and closes without holding a warm sandbox; a one-shot run must carry a prompt, since nothing can ever be sent to it later. Sessions on the Codex harness are one-shot regardless.",
    )
    metadata: dict[str, str] = Field(
        default_factory=dict,
        description="Arbitrary string key/value metadata stored on the session.",
    )
    output: Union[OutputConfig, None] = Field(
        default=None,
        description="The structured-output exit contract for this session.",
    )
    permissions: Union[PermissionsConfig, None] = Field(
        default=None, description="What the session may touch, per minted credential."
    )
    prompt: Union[str, None] = Field(
        default=None,
        description="The session's first message. Omit it and the session starts idle: the sandbox spins up, the agent waits at the prompt, and the first message you send opens turn 0.",
    )
    repositories: Union[list[str], None] = Field(
        default=None,
        description="Repositories to check out in addition to the environment's own, as `owner/name` or a bare `name` (the account's). Each is added only when the resolved environment does not already have it — the CLI sends the repository it is standing in this way, whatever environment the session runs in.",
    )
    skills: Union[list[SkillRef], None] = Field(
        default=None, description="Skills installed for this session."
    )


class StartAutomationSessionRequest(EllipsisModel):
    """Parameters for invoking an automation. Deliberately tiny: the
    automation's definition binds (persona, model, environment, permissions,
    skills, budget); a caller supplies only its typed input, an optional
    tighter budget, and metadata. Anything else is a 422 — to run with a
    different persona or environment, start a raw session instead.
    """

    budget: Union[float, None] = Field(
        default=None,
        description="Tighten this run's spend cap, in US dollars. May only lower the automation's own session budget; a higher number, or one above the organization's ceiling, is a 400.",
    )
    input: Union[dict[str, Any], None] = Field(
        default=None,
        description="The typed payload for an automation that declares input.json_schema: validated against it (422 on mismatch) and rendered into the session's first message through the automation's input.message template. Required when the automation declares a schema; a 422 when it does not.",
    )
    metadata: dict[str, str] = Field(
        default_factory=dict,
        description="Arbitrary string key/value metadata stored on the session.",
    )


class StartCliAuthResponse(EllipsisModel):
    """A freshly minted device-code flow: show the user code (or open the
    complete URI) and poll with the device code.
    """

    device_code: str = Field(
        description="The secret the CLI polls with. Never shown to the human."
    )
    expires_in: int = Field(
        description="Seconds until the flow expires and a new one must be started."
    )
    interval: int = Field(description="Minimum seconds to wait between polls.")
    user_code: str = Field(
        description="The short code the human enters (or confirms) in the dashboard."
    )
    verification_uri: str = Field(
        description="The dashboard page where the human approves the flow."
    )
    verification_uri_complete: str = Field(
        description="The approval page with the user code pre-filled — open this directly."
    )


